static Competition league(int a,int b,int year){Competition C;C.kind=1;C.name="Championnat test du musée";C.format=FMT_LEAGUE;Stage s;s.type=ST_LEAGUE;s.groups={{a,b}};MatchRes m;m.home=a;m.away=b;m.hg=3;m.ag=0;m.played=true;m.group=0;C.matches.push_back(m);Round r;r.m={0};r.time=10;s.rounds.push_back(r);C.stages.push_back(s);C.done=true;C.winner=year==2?a:b;return C;}
