 g_career.museumLeave(a);check(g_career.clubHistories[a].managers.back().toYear==2030,"manager departure archived");g_career.userTeam=b;g_career.museumState(b);check(g_career.clubHistories[a].seasons.size()==5,"club change retains former museum");
 if(FILE* f=fopen("build/test-legacy-v28.sav","rb")){fclose(f);check(g_career.load("build/test-legacy-v28.sav"),"build4 save version28 load");check(g_career.clubHistories.empty(),"old save has no invented museum history");g_career.museumState(g_career.userTeam);check(g_career.clubHistories.size()==1,"legacy starts archives on use");}
 g_career.userTeam=a;g_career.mgr.projects.clear();g_career.mgr.budget=100000;g_world.teams[a].sta.museum=1;Project project;project.kind=PJ_MUSEUM;std::string error;check(g_career.startProject(project,error),"second museum level can be constructed");for(int month=0;month<4;month++)stadiumMonth(g_career);check(g_world.teams[a].sta.museum==2,"museum construction reaches level2");check(!g_career.startProject(project,error),"no third museum level");
 // Reject truncated / excessively sized museum vectors before allocating them.
